import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"
import { Spinner } from "@/components/ui/spinner"

/**
 * Green Control button.
 * Square. One `primary` per view: the person's next decision (Investigate, Apply, Assign).
 * States: hover, focus-visible, active (press), disabled, loading.
 * When `loading`, the label should say what is happening ("Applying…").
 */
const buttonVariants = cva(
  "inline-flex shrink-0 cursor-pointer items-center justify-center gap-2 whitespace-nowrap rounded-none font-medium outline-none transition-[background-color,transform,opacity] duration-[260ms] ease-spring active:duration-75 active:ease-out focus-visible:outline-[1.5px] focus-visible:outline-offset-2 focus-visible:outline-foreground active:scale-[0.97] disabled:cursor-not-allowed disabled:opacity-40 disabled:active:scale-100 motion-reduce:transition-none",
  {
    variants: {
      variant: {
        primary: "bg-primary text-primary-foreground hover:bg-primary/80 active:bg-primary/65",
        secondary: "bg-transparent text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-secondary active:bg-secondary",
        ghost: "bg-transparent text-muted-foreground hover:bg-secondary hover:text-foreground",
      },
      size: {
        default: "h-9 px-3.5 text-sm",
        sm: "h-8 px-3 text-[13px]",
      },
    },
    defaultVariants: { variant: "primary", size: "default" },
  }
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  /** Sent and waiting. Locks the button and shows a spinner. */
  loading?: boolean
}

export function Button({ className, variant, size, loading = false, disabled, children, ...props }: ButtonProps) {
  return (
    <button
      data-slot="button"
      aria-busy={loading || undefined}
      disabled={disabled || loading}
      className={cn(buttonVariants({ variant, size }), loading && "cursor-progress disabled:opacity-100", className)}
      {...props}
    >
      {loading && <Spinner />}
      {children}
    </button>
  )
}

export { buttonVariants }
